def _head_parking_meter() -> dict[str, Any]:
    rects: list[list[Any]] = [[x, y, 8, 8, 'm'] for x, y in INNER.values()]
    for side in ('left', 'right'):
        sx, sy = INNER[side]
        rects.append([sx, sy, 8, 1, 'd'])
        rects.append([sx + 2, sy + 2, 4, 4, 'l'])
    bx, by = INNER['back']
    rects.append([bx + 1, by + 1, 6, 6, 'd'])
    rects.append([bx + 2, by + 2, 4, 4, 'm'])
    tx, ty = INNER['top']
    rects.append([tx + 1, ty + 1, 6, 6, 'd'])
    rects.append([tx + 2, ty + 2, 4, 4, 's'])
    fx, fy = INNER['front']
    rects.extend([
        [fx + 1, fy + 1, 6, 4, 'd'],
        [fx + 2, fy + 2, 4, 2, 'c'],
        [fx + 2, fy + 6, 2, 1, 'r'],
        [fx + 5, fy + 6, 1, 1, 'c'],
        [fx + 5, fy + 5, 1, 1, 'w'],
    ])
    ofx, ofy = OUTER['front']
    rects.extend([
        [ofx + 1, ofy, 6, 1, 'l'],
        [ofx, ofy + 1, 1, 4, 'd'],
        [ofx + 7, ofy + 1, 1, 4, 'd'],
    ])
    otx, oty = OUTER['top']
    rects.append([otx + 1, oty + 6, 6, 2, 'l'])
    return {
        'colors': {
            'm': '#6e777d',
            'l': '#98a3aa',
            'd': '#1f282e',
            's': '#2d4b6e',
            'c': '#4ee08e',
            'r': '#d64545',
            'w': '#f4f7f8',
        },
        'rects': rects,
    }


def _head_hvac_vent() -> dict[str, Any]:
    rects: list[list[Any]] = [[x, y, 8, 8, 'm'] for x, y in INNER.values()]
    for side in ('left', 'right', 'top', 'bottom'):
        sx, sy = INNER[side]
        rects.append([sx + 1, sy + 1, 6, 6, 'l'])
    bx, by = INNER['back']
    rects.extend([
        [bx + 1, by + 1, 6, 6, 'm'],
        [bx + 2, by + 2, 1, 1, 'd'],
        [bx + 5, by + 2, 1, 1, 'd'],
        [bx + 2, by + 5, 1, 1, 'd'],
        [bx + 5, by + 5, 1, 1, 'd'],
    ])
    fx, fy = INNER['front']
    rects.extend([
        [fx + 1, fy + 1, 6, 6, 'd'],
        [fx + 1, fy + 2, 6, 1, 'l'],
        [fx + 1, fy + 4, 6, 1, 'l'],
        [fx + 1, fy + 6, 6, 1, 'l'],
    ])
    ofx, ofy = OUTER['front']
    rects.extend([
        [ofx, ofy, 8, 1, 'h'],
        [ofx, ofy + 7, 8, 1, 'h'],
        [ofx + 1, ofy + 2, 6, 1, 'm'],
        [ofx + 1, ofy + 4, 6, 1, 'm'],
    ])
    otx, oty = OUTER['top']
    rects.extend([
        [otx + 1, oty + 1, 6, 1, 'h'],
        [otx + 1, oty + 6, 6, 1, 'h'],
    ])
    return {
        'colors': {
            'm': '#8b959b',
            'l': '#adb7bd',
            'h': '#cfd6da',
            'd': '#1a2024',
        },
        'rects': rects,
    }


def _head_mailbox() -> dict[str, Any]:
    rects: list[list[Any]] = [[x, y, 8, 8, 'o'] for x, y in INNER.values()]
    tx, ty = INNER['top']
    rects.append([tx + 1, ty + 1, 6, 6, 'h'])
    bx, by = INNER['back']
    rects.append([bx + 2, by + 2, 4, 4, 'd'])
    for side in ('left', 'right'):
        sx, sy = INNER[side]
        rects.append([sx, sy, 8, 1, 'd'])
        rects.append([sx, sy + 7, 8, 1, 'd'])
    fx, fy = INNER['front']
    rects.extend([
        [fx + 1, fy + 1, 6, 2, 'k'],
        [fx + 2, fy + 4, 4, 3, 'w'],
        [fx + 3, fy + 5, 2, 1, 'k'],
    ])
    ofx, ofy = OUTER['front']
    rects.extend([
        [ofx + 1, ofy, 6, 1, 'h'],
        [ofx + 1, ofy + 1, 6, 1, 'd'],
    ])
    otx, oty = OUTER['top']
    rects.append([otx + 1, oty + 6, 6, 2, 'h'])
    return {
        'colors': {
            'o': '#e07224',
            'h': '#f29346',
            'd': '#a84c12',
            'k': '#1b1f23',
            'w': '#f7f5ee',
        },
        'rects': rects,
    }


def art_example(task: str) -> dict[str, Any]:
    spec = ART_TASKS[task]
    if spec['track'] == 'loom-banner':
        return {'base': spec['base'], 'layers': [list(layer) for layer in spec['target_layers']]}
    if task in _MAP_ART_EXAMPLES:
        data = _MAP_ART_EXAMPLES[task]
        return {'colors': dict(data['colors']), 'rects': [list(r) for r in data['rects']]}
    builders = {
        'head-parking-meter': _head_parking_meter,
        'head-hvac-vent': _head_hvac_vent,
        'head-mailbox': _head_mailbox,
    }
    return builders[task]()
